<template><section class="black-screen-tool" aria-label="综合故障排查树"><p class="diagnostic-note">4 大故障类别，收录 {{catalogCount}} 类常见症状。先选择电脑硬件、网络、系统与驱动或紧急与其他，再进入具体排查。根据所选检查结果提供方向，不自动检测或修改系统；型号特有问题以厂商手册为准。</p><div v-if="trail.length===1" class="diagnostic-search"><label for="hardware-symptom-search">搜索故障症状</label><input id="hardware-symptom-search" v-model="search" type="search" placeholder="例如 蓝屏 / SSD / 不充电 / USB" /><div v-if="search.trim()" class="diagnostic-choices"><button v-for="entry in searchResults" :key="entry.next" type="button" @click="choose(entry)">{{entry.majorLabel}} / {{entry.category}} · {{entry.label}}</button><p v-if="!searchResults.length">没有匹配项，可清空搜索或选择“其他与综合”。</p></div></div><div class="diagnostic-actions"><button type="button" :disabled="trail.length===1" @click="back">上一步</button><button type="button" @click="restart">重新开始</button><button type="button" @click="copy">复制排查记录</button></div><article v-if="!search.trim()" class="diagnostic-node" aria-live="polite"><small>当前路径第 {{trail.length}} 步</small><h3 ref="question" tabindex="-1">{{node.title}}</h3><p>{{node.text}}</p><div class="diagnostic-choices"><button v-for="option in node.options||[]" :key="option.label" type="button" @click="choose(option)">{{option.label}}</button></div></article><section v-if="result" class="diagnostic-result" aria-label="可能的排查结果" aria-live="polite"><h3>可能结果：{{result.title}}</h3><p><strong>{{result.status}}</strong></p><h4>可能原因</h4><ul><li v-for="cause in result.causes" :key="cause">{{cause}}</li></ul><p><strong>判断依据：</strong>{{result.evidence}}</p><p><strong>下一步建议：</strong>{{result.next}}</p><p class="diagnostic-note">{{result.note}}</p></section><p role="status">{{feedback}}</p><details><summary>查看排查记录（{{trail.length}} 步）</summary><pre>{{record}}</pre></details><p class="diagnostic-sources"><a href="https://support.microsoft.com/en-us/windows/experience/performance-optimization/troubleshooting-windows-unexpected-restarts-and-stop-code-errors" target="_blank" rel="noopener noreferrer">蓝屏与重启排查 ↗</a><a href="https://www.asus.com/ca-en/support/faq/1015064/" target="_blank" rel="noopener noreferrer">散热排查 ↗</a><a href="https://support.microsoft.com/en-us/windows/hardware/audio/fix-sound-or-audio-problems-in-windows" target="_blank" rel="noopener noreferrer">音频排查 ↗</a><a href="https://www.dell.com/support/kbdoc/en-us/000124389/how-to-troubleshoot-power-issues-on-a-dell-laptop" target="_blank" rel="noopener noreferrer">笔记本供电排查 ↗</a><a href="https://support.microsoft.com/en-us/windows/hardware/display-graphics/troubleshooting-blank-screens-in-windows" target="_blank" rel="noopener noreferrer">微软黑屏排查 ↗</a><a href="https://www.msi.com/support/technical_details/MB_Boot_No_Display" target="_blank" rel="noopener noreferrer">主板无显示排查 ↗</a></p></section></template>
<script>
import {diagnosticNodes,diagnosticRecord,diagnosticResult,diagnosticCatalog} from '../data/black-screen-diagnostic.mjs';
export default {name:'BlackScreenDiagnostic',data:()=>({trail:[{id:'start',choice:''}],feedback:'',search:''}),computed:{catalogCount(){return diagnosticCatalog.length;},searchResults(){const words=this.search.trim().toLowerCase().split(/\s+/).filter(Boolean);return diagnosticCatalog.filter(c=>words.every(w=>(c.label+' '+c.category+' '+c.majorLabel+' '+c.keywords).toLowerCase().includes(w)));},node(){return diagnosticNodes[this.trail[this.trail.length-1].id];},record(){return diagnosticRecord(this.trail);},result(){return diagnosticResult(this.trail);}},methods:{focus(){this.$nextTick(()=>this.$refs.question?.focus());},choose(option){this.search='';this.trail[this.trail.length-1].choice=option.label;this.trail.push({id:option.next,choice:''});this.feedback='';this.focus();},back(){if(this.trail.length>1){this.trail.pop();this.trail[this.trail.length-1].choice='';this.feedback='';this.focus();}},restart(){this.search='';this.trail=[{id:'start',choice:''}];this.feedback='';this.focus();},async copy(){try{await navigator.clipboard.writeText(this.record);this.feedback='已复制排查记录';}catch{this.feedback='请展开排查记录并选中文字手动复制';}}}};
</script>
<style scoped>.diagnostic-search{margin:14px 0;}.diagnostic-search label{display:block;margin-bottom:6px;}.diagnostic-search input{box-sizing:border-box;width:100%;padding:10px;color:inherit;background:var(--el-fill-color-blank);border:1px solid var(--el-border-color);font:inherit;}.black-screen-tool{line-height:1.8;}.diagnostic-actions,.diagnostic-choices{display:flex;flex-wrap:wrap;gap:10px;margin:14px 0;}button{font:inherit;padding:9px 12px;border:1px solid var(--el-border-color);color:inherit;background:var(--el-fill-color-blank);cursor:pointer;max-width:100%;white-space:normal;text-align:left;}button:disabled{opacity:.4;cursor:default;}.diagnostic-result{margin:16px 0;padding:18px;border:1px solid var(--ui-accent);background:var(--el-fill-color-light);border-radius:3px;overflow-wrap:anywhere;}.diagnostic-result h3{font-size:17px;margin:0 0 10px;}.diagnostic-node{padding:18px;border:1px solid var(--el-border-color-light);background:var(--el-fill-color-blank);border-radius:3px;}.diagnostic-node h3{font-size:17px;margin:8px 0;}.diagnostic-note,.diagnostic-node p,small{color:var(--el-text-color-secondary);}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit;}summary{cursor:pointer;}.diagnostic-sources{display:flex;flex-wrap:wrap;gap:16px;}a{color:var(--ui-accent);}h3:focus-visible{outline:2px solid var(--ui-focus);outline-offset:4px;}</style>
